chartjs.data:
model -> {
	period = ifElse(isEmpty($model),
		new(`tl.ai.monitor:Period`, transient: true)
			..set(`tl.ai.monitor:Period#preset`, 30),
		$model);
	executions = all(`tl.ai.execution:AgentExecution`);
	startedAt = e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`);
	cost = e -> $e.get(`tl.ai.execution:AgentExecution#cost`);
	start = $period.get(`tl.ai.monitor:Period#windowStart`);
	end = $period.get(`tl.ai.monitor:Period#windowEnd`);
	recent = $executions.filter(e -> (isEmpty($start) || $startedAt($e) >= $start)
		&& (isEmpty($end) || $startedAt($e) < $end));
	priced = $recent.filter(e -> !isEmpty($cost($e)));
	owner = e -> toString($e.get(`tl.ai.execution:AgentExecution#session`)
		.get(`tl.ai.execution:AgentSession#owner`));
	byOwner = $priced.groupBy(e -> $owner($e));
	ranked = $byOwner.keySet().toList().sort(desc(comparator(o -> $byOwner[$o].map(e -> $cost($e)).sum())));
	names = ifElse($ranked.size() > 10, $ranked.subList(0, 10), $ranked);
	currencies = $priced.map(e -> $e.get(`tl.ai.execution:AgentExecution#currency`)).toSet().toList().sort();
	// Dollars, the currency of the price lists, in a colour of their own: the two currencies a
	// period that spans a change of currency most likely shows are told apart at a glance.
	colorOf = c -> ifElse($c == 'USD', '#8a3ffc', '#2968c8');
	{
		'type': 'bar',
		'data': {
			'labels': $names,
			'datasets': $currencies.map(c -> {
				dataset = {
					'label': $c,
					'data': $names.map(o -> $byOwner[$o]
						.filter(e -> $e.get(`tl.ai.execution:AgentExecution#currency`) == $c)
						.map(e -> $cost($e)).sum()),
					'backgroundColor': $colorOf($c),
					'maxBarThickness': 26
				};
				$dataset;
			})
		},
		'options': {
			'indexAxis': 'y',
			'maintainAspectRatio': false,
			'plugins': {
				// The currency is the legend: with one currency it names the unit of the axis.
				'legend': { 'display': !isEmpty($currencies) },
				// See the note in topAgentsChart.xml: an empty plot area has to say why it
				// is empty, because "no data" and "no consumption" look the same.
				'title': {
					'display': isEmpty($priced),
					'text': ifElse(!isEmpty($start) && $start > now(),
						#('The selected period lies in the future.'@en,
							'Der gewählte Zeitraum liegt in der Zukunft.'@de).localize(),
						#('No runs with a recorded cost in the selected period.'@en,
							'Keine Läufe mit erfassten Kosten im gewählten Zeitraum.'@de).localize()),
					'color': '#8a8a8a'
				}
			},
			'scales': { 'x': { 'beginAtZero': true } }
		}
	};
}
